// Package txsaga 提供可嵌入应用的 Saga 编排能力：带补偿的顺序步骤执行、
// 基于业务键与外部幂等键的执行身份去重，以及与状态原子共写的 Outbox 事件。
//
// 本包只依赖 Go 标准库，不规定任何磁盘文件格式；状态持久化由 Store 接口承载。
package txsaga

import (
	"context"
	"errors"
	"time"
)

// 终态状态：执行一旦进入以下任一状态即固定，后续同一执行身份的调用直接返回既有结果。
const (
	// StatusCompleted 所有正向步骤均已确认成功。
	StatusCompleted = "completed"
	// StatusFailed 某正向步骤失败，且此前确认成功步骤的补偿均已成功。
	StatusFailed = "failed"
	// StatusCompensationFailed 正向失败后，补偿过程中发生错误，结果固定在此状态。
	StatusCompensationFailed = "compensation_failed"
)

// 中间状态：执行尚未到达终态。
const (
	// StatusRunning 至少一个步骤已确认成功，仍有步骤待执行。
	StatusRunning = "running"
	// StatusCompensating 正向步骤已失败，正在逆序补偿此前确认成功的步骤。
	StatusCompensating = "compensating"
)

// 步骤处理结果。
const (
	// StepResultPending 步骤尚未被执行到（仅出现在 Result 中，持久状态以空串表示）。
	StepResultPending = "pending"
	// StepResultSucceeded 正向动作已确认成功。
	StepResultSucceeded = "succeeded"
	// StepResultFailed 正向动作返回错误（该步骤未确认成功，不会被补偿）。
	StepResultFailed = "failed"
	// StepResultCompensated 补偿动作已确认成功。
	StepResultCompensated = "compensated"
	// StepResultCompensationFailed 补偿动作返回错误（补偿步骤未确认，允许重试）。
	StepResultCompensationFailed = "compensation_failed"
)

// Outbox 事件类型，随状态变化追加。
const (
	// EventExecutionStarted 一次执行开始（首个步骤执行前）。
	EventExecutionStarted = "execution_started"
	// EventStepSucceeded 某正向步骤已提交成功状态。
	EventStepSucceeded = "step_succeeded"
	// EventStepFailed 某正向步骤失败，执行转入补偿。
	EventStepFailed = "step_failed"
	// EventStepCompensated 某步骤补偿已提交。
	EventStepCompensated = "step_compensated"
	// EventStepCompensationFailed 某步骤补偿失败。
	EventStepCompensationFailed = "step_compensation_failed"
	// EventExecutionCompleted 全部正向步骤完成，执行到达 completed 终态。
	EventExecutionCompleted = "execution_completed"
	// EventExecutionFailed 补偿全部完成，执行到达 failed 终态。
	EventExecutionFailed = "execution_failed"
	// EventCompensationFailed 补偿异常，执行到达 compensation_failed 终态。
	EventCompensationFailed = "compensation_failed"
)

// 哨兵错误，调用方可用 errors.Is 判定。
var (
	// ErrInvalidDefinition 定义非法（名称为空、步骤为空、步骤名为空、
	// 缺少正向动作）或执行请求缺少外部幂等键。
	ErrInvalidDefinition = errors.New("txsaga: invalid saga definition")
	// ErrExecutionNotFound 未知执行身份：该业务键下不存在由给定 Saga 定义
	// 与外部幂等键标识的执行。
	ErrExecutionNotFound = errors.New("txsaga: execution not found")
	// ErrDefinitionConflict 相同业务键已绑定不同的 Saga 定义。
	// 同一业务键上的所有执行必须共用同一份定义。
	ErrDefinitionConflict = errors.New("txsaga: saga definition conflict for business key")
)

// ActionFunc 是一个步骤的正向幂等动作。
//
// 动作必须遵守幂等契约：同一步骤在进程崩溃、调用超时后可能被再次调用，
// 重复调用不得产生重复的业务效果。动作返回 nil 即视为该步骤确认成功，
// 之后引擎先提交成功状态，再执行下一步。
type ActionFunc func(ctx context.Context, exec ExecutionView) error

// CompensationFunc 是已确认成功步骤的补偿幂等动作。
//
// 补偿按步骤成功顺序的相反方向逐个执行。补偿同样可能被重复调用，
// 实现必须自身幂等。返回 nil 表示补偿确认成功；返回错误时执行固定在
// compensation_failed 终态，未确认的补偿允许在后续调用中重试（终态结果不变）。
type CompensationFunc func(ctx context.Context, exec ExecutionView) error

// Step 定义 Saga 中的一个正向步骤及其补偿。
type Step struct {
	// Name 步骤在 Saga 内唯一的名称。
	Name string
	// Action 正向幂等动作，必填。
	Action ActionFunc
	// Compensate 反向补偿动作；无需补偿的步骤可留空，留空视为补偿成功。
	Compensate CompensationFunc
}

// Definition 是一个 Saga 的不可变定义。
type Definition struct {
	// Name Saga 定义名称；同时参与执行身份判定。
	Name string
	// Version 定义版本，参与定义指纹以区分同名但内容不同的定义。
	Version string
	// Steps 按正向执行顺序排列的步骤，至少一个。
	Steps []Step
}

// ExecutionRequest 发起一次 Saga 执行。
type ExecutionRequest struct {
	// BusinessKey 调用方的唯一业务键（如订单号），必填。
	BusinessKey string
	// IdempotencyKey 外部幂等键，必填；与业务键、Saga 定义共同确定执行身份。
	IdempotencyKey string
	// Payload 透传给动作的结构化业务输入，可为 nil。
	Payload any
}

// StepOutcome 是单个步骤在一次执行中的处理结果。
type StepOutcome struct {
	// Name 步骤名。
	Name string `json:"name"`
	// Result 取值为 StepResult* 常量。
	Result string `json:"result"`
	// Attempts 正向动作的实际调用次数；同身份重试已确认步骤时保持不变，
	// 大于 1 说明该未确认步骤曾被重复调用（动作须幂等）。
	Attempts int `json:"attempts"`
	// CompensationAttempts 补偿动作的实际调用次数；已确认补偿后保持不变。
	CompensationAttempts int `json:"compensation_attempts,omitempty"`
	// Error 最近一次失败原因；成功时为空。
	Error string `json:"error,omitempty"`
	// StartedAt 最近一次开始执行正向动作的时间，未执行过为零值。
	StartedAt time.Time `json:"started_at,omitempty"`
	// FinishedAt 最近一次正向动作返回的时间，未完成则为零值。
	FinishedAt time.Time `json:"finished_at,omitempty"`
}

// Result 是一次执行在某次调用后返回的确定状态快照。
type Result struct {
	// BusinessKey 业务键。
	BusinessKey string `json:"business_key"`
	// SagaName Saga 定义名称。
	SagaName string `json:"saga_name"`
	// IdempotencyKey 外部幂等键。
	IdempotencyKey string `json:"idempotency_key"`
	// Status 当前状态，取值为 Status* 常量；终态之一表示已确定。
	Status string `json:"status"`
	// FailureReason 正向失败原因；仅在 failed/compensation_failed 时非空。
	FailureReason string `json:"failure_reason,omitempty"`
	// CompensationError 最近一次补偿错误；仅 compensation_failed 时非空。
	CompensationError string `json:"compensation_error,omitempty"`
	// FailedStep 正向失败的步骤名；未失败为空。
	FailedStep string `json:"failed_step,omitempty"`
	// FailedCompensationStep 补偿失败的步骤名；未发生为空。
	FailedCompensationStep string `json:"failed_compensation_step,omitempty"`
	// Steps 各步骤处理结果，顺序与定义中的正向顺序一致。
	Steps []StepOutcome `json:"steps"`
	// Terminal 是否为固定终态。终态结果在后续调用中保持不变。
	Terminal bool `json:"terminal"`
}

// ExecutionView 是传给动作与补偿的执行只读视图。
type ExecutionView interface {
	// BusinessKey 返回本次执行的业务键。
	BusinessKey() string
	// SagaName 返回 Saga 定义名称。
	SagaName() string
	// IdempotencyKey 返回外部幂等键。
	IdempotencyKey() string
	// Payload 返回发起执行时透传的结构化负载。
	Payload() any
	// SucceededSteps 返回截至当前已确认成功的步骤名（按成功顺序）。
	SucceededSteps() []string
}

// Event 是随状态变化追加的 Outbox 事件。
type Event struct {
	// ID 事件唯一 ID，由存储在追加时分配。
	ID string
	// BusinessKey 业务键。
	BusinessKey string
	// Type 事件类型，取值为 Event* 常量。
	Type string
	// OccurredAt 事件发生时间（状态提交时刻）。
	OccurredAt time.Time
	// Payload 结构化负载，使用 encoding/json 可直接序列化。
	Payload any

	// 投递元数据，由 Claim/Ack/Nack 维护，不参与业务语义。
	deliveries    int
	lastAttemptAt time.Time
}

// Deliveries 返回该事件已进入领取/投递流程的次数（含首次）。
// 发送失败后保留事件并增加投递次数，调用方可据此判断是否重复投递。
func (e *Event) Deliveries() int { return e.deliveries }

// LastAttemptAt 返回最近一次领取时间；从未被领取为零值。
func (e *Event) LastAttemptAt() time.Time { return e.lastAttemptAt }

// EventPayload 是事件的结构化负载。
type EventPayload struct {
	SagaName       string `json:"saga_name"`
	IdempotencyKey string `json:"idempotency_key"`
	Step           string `json:"step,omitempty"`
	Status         string `json:"status,omitempty"`
	Reason         string `json:"reason,omitempty"`
	Attempt        int    `json:"attempt,omitempty"`
	// SucceededSteps 事件发生时已确认成功的步骤顺序快照。
	SucceededSteps []string `json:"succeeded_steps,omitempty"`
}

package txsaga

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"
	"time"
)

// StepState 是单个步骤的持久状态。取值见 StepResult* 常量；
// 空串表示该步骤尚未被执行到（pending）。
type StepState struct {
	Name   string `json:"name"`
	Status string `json:"status"`
	// Attempts 正向动作被实际调用的次数；已确认成功后重试不会增加。
	Attempts   int       `json:"attempts"`
	LastError  string    `json:"last_error,omitempty"`
	StartedAt  time.Time `json:"started_at,omitempty"`
	FinishedAt time.Time `json:"finished_at,omitempty"`
	// CompensationAttempts 补偿动作被实际调用的次数；已确认补偿后重试不会增加。
	CompensationAttempts int       `json:"compensation_attempts,omitempty"`
	CompensatedAt        time.Time `json:"compensated_at,omitempty"`
}

// ExecutionState 是一次执行的完整持久状态，Store 的实现负责其持久化。
// 本包不规定磁盘文件格式：实现可自行选择 JSON、数据库行等任何载体。
type ExecutionState struct {
	BusinessKey            string      `json:"business_key"`
	SagaName               string      `json:"saga_name"`
	IdempotencyKey         string      `json:"idempotency_key"`
	Fingerprint            string      `json:"fingerprint"`
	Status                 string      `json:"status"`
	Steps                  []StepState `json:"steps"`
	FailureReason          string      `json:"failure_reason,omitempty"`
	FailedStep             string      `json:"failed_step,omitempty"`
	CompensationError      string      `json:"compensation_error,omitempty"`
	FailedCompensationStep string      `json:"failed_compensation_step,omitempty"`
	Payload                any         `json:"-"`
	CreatedAt              time.Time   `json:"created_at"`
	UpdatedAt              time.Time   `json:"updated_at"`
}

// Terminal 报告状态是否为固定终态。
func (s *ExecutionState) Terminal() bool {
	switch s.Status {
	case StatusCompleted, StatusFailed, StatusCompensationFailed:
		return true
	default:
		return false
	}
}

// Binding 是业务键与 Saga 定义的绑定关系。同一业务键首次执行后即绑定其定义，
// 之后以不同定义执行将得到 ErrDefinitionConflict。
type Binding struct {
	SagaName    string
	Fingerprint string
}

// Tx 是一次原子状态提交的事务视图。
//
// 引擎在 Commit 的回调中通过本接口读取既有状态、写入新状态并追加事件；
// 回调返回 nil 时，状态变更与全部事件由 Store 原子持久化，
// 回调返回错误时二者一并丢弃。基于内存的实现以互斥锁保证该原子性，
// 其它实现应使用数据库事务等同等机制。
type Tx interface {
	// Binding 返回该业务键当前绑定的 Saga 定义；未绑定时 ok 为 false。
	Binding() (b Binding, ok bool)
	// State 返回当前执行状态的可修改副本；执行尚不存在时返回 nil。
	// 对返回对象的修改仅在回调成功返回后生效。
	State() *ExecutionState
	// Create 建立执行状态（同时建立业务键与定义的绑定）。
	// 状态的 CreatedAt/UpdatedAt 由 Store 填写。
	Create(state *ExecutionState)
	// AppendEvent 追加一条 Outbox 事件。事件 ID 与发生时间由 Store 分配。
	// 事件与本次状态修改在同一事务中落盘。
	AppendEvent(eventType string, payload EventPayload)
}

// Snapshot 是某执行身份的只读快照。
type Snapshot struct {
	// State 执行状态；该身份尚无执行时为 nil。
	State *ExecutionState
	// Binding 业务键的定义绑定；未绑定时 ok 为 false。
	Binding Binding
	// Bound 是否存在绑定。
	Bound bool
}

// Store 是执行状态与 Outbox 事件的存储。
//
// 实现必须保证 Commit 的原子性：执行状态与当次追加的事件要么全部可见，
// 要么全部不可见。本包不规定落盘格式。
type Store interface {
	// LoadSnapshot 读取执行身份 (businessKey, idempotencyKey) 的状态快照，
	// 同时返回该业务键的定义绑定。
	LoadSnapshot(ctx context.Context, businessKey, idempotencyKey string) (Snapshot, error)

	// Commit 在一个原子事务中运行 fn 并提交其修改与追加的事件。
	Commit(ctx context.Context, businessKey, idempotencyKey string, fn func(tx Tx) error) error

	// ClaimPendingEvents 领取至多 max 条尚未投递（含此前发送失败被退回）
	// 的事件。每次领取即代表一次投递尝试，事件的 Deliveries 计数加一；
	// 被领取但未 Ack/Nack 的事件不会被再次领取。max<=0 表示实现自选批量。
	ClaimPendingEvents(ctx context.Context, max int) ([]*Event, error)

	// AckEvent 标记事件已投递成功，事件不再参与后续领取。
	AckEvent(ctx context.Context, eventID string) error

	// NackEvent 发送失败后退回事件：保留原事件与负载、解除领取锁定，
	// 允许继续领取。投递次数由再次领取时累计。
	NackEvent(ctx context.Context, eventID string) error
}

// fingerprint 计算定义指纹：名称、版本与有序步骤名共同决定。
// 动作函数无可比较标识，调用方应通过 Name/Version 区分不同实现。
func fingerprint(d Definition) string {
	h := sha256.New()
	fmt.Fprintf(h, "name=%s\x00version=%s", d.Name, d.Version)
	for _, s := range d.Steps {
		fmt.Fprintf(h, "\x00step=%s", s.Name)
		if s.Compensate != nil {
			h.Write([]byte("\x00comp=1"))
		}
	}
	return hex.EncodeToString(h.Sum(nil))
}

// ---- 内存实现 ----

type memEvent struct {
	event   Event
	claimed bool
}

type memTx struct {
	s        *MemoryStore
	business string
	idem     string
	binding  *Binding
	state    *ExecutionState
	created  bool
	staged   []Event
}

func (t *memTx) Binding() (Binding, bool) {
	if t.binding != nil {
		return *t.binding, true
	}
	return Binding{}, false
}

func (t *memTx) State() *ExecutionState { return t.state }

func (t *memTx) Create(state *ExecutionState) {
	state.BusinessKey = t.business
	state.IdempotencyKey = t.idem
	t.state = state
	t.created = true
}

func (t *memTx) AppendEvent(eventType string, p EventPayload) {
	t.staged = append(t.staged, Event{
		BusinessKey: t.business,
		Type:        eventType,
		Payload:     p,
	})
}

// MemoryStore 是进程内的 Store 实现，仅依赖标准库，适用于嵌入与测试。
// 不向磁盘写入任何文件；进程退出后状态不保留。
type MemoryStore struct {
	mu       sync.Mutex
	execs    map[string]*ExecutionState
	bindings map[string]Binding
	events   map[string]*memEvent
	pending  []string // 未领取事件 ID，保持追加顺序
	seq      uint64
	now      func() time.Time
}

// NewMemoryStore 创建内存状态存储。
func NewMemoryStore() *MemoryStore {
	return &MemoryStore{
		execs:    make(map[string]*ExecutionState),
		bindings: make(map[string]Binding),
		events:   make(map[string]*memEvent),
		now:      time.Now,
	}
}

func execID(businessKey, idempotencyKey string) string {
	return businessKey + "\x00" + idempotencyKey
}

func cloneState(s *ExecutionState) *ExecutionState {
	if s == nil {
		return nil
	}
	c := *s
	if s.Steps != nil {
		c.Steps = append([]StepState(nil), s.Steps...)
	}
	return &c
}

// LoadSnapshot 实现 Store 接口。
func (s *MemoryStore) LoadSnapshot(_ context.Context, businessKey, idempotencyKey string) (Snapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	snap := Snapshot{}
	if b, ok := s.bindings[businessKey]; ok {
		snap.Binding, snap.Bound = b, true
	}
	if st, ok := s.execs[execID(businessKey, idempotencyKey)]; ok {
		snap.State = cloneState(st)
	}
	return snap, nil
}

// Commit 实现 Store 接口：整库加锁，状态与事件原子可见。
func (s *MemoryStore) Commit(_ context.Context, businessKey, idempotencyKey string, fn func(Tx) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	t := &memTx{s: s, business: businessKey, idem: idempotencyKey}
	if b, ok := s.bindings[businessKey]; ok {
		bc := b
		t.binding = &bc
	}
	if st, ok := s.execs[execID(businessKey, idempotencyKey)]; ok {
		t.state = cloneState(st)
	}

	if err := fn(t); err != nil {
		return err // 回调失败： staged 事件与状态副本一并丢弃
	}

	now := s.now()
	if t.state != nil {
		if t.created {
			if _, exists := s.execs[execID(businessKey, idempotencyKey)]; exists {
				return errors.New("txsaga: execution already exists")
			}
			t.state.CreatedAt = now
			// 首次执行建立业务键与定义的绑定；同键的后续执行定义一致，覆盖无害。
			if _, ok := s.bindings[businessKey]; !ok {
				s.bindings[businessKey] = Binding{SagaName: t.state.SagaName, Fingerprint: t.state.Fingerprint}
			}
		}
		t.state.UpdatedAt = now
		s.execs[execID(businessKey, idempotencyKey)] = cloneState(t.state)
	}

	for i := range t.staged {
		ev := t.staged[i]
		s.seq++
		ev.ID = fmt.Sprintf("evt-%020d", s.seq)
		ev.OccurredAt = now
		s.events[ev.ID] = &memEvent{event: ev}
		s.pending = append(s.pending, ev.ID)
	}
	return nil
}

// ClaimPendingEvents 实现 Store 接口。
func (s *MemoryStore) ClaimPendingEvents(_ context.Context, max int) ([]*Event, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if max <= 0 {
		max = 16
	}
	now := s.now()
	out := make([]*Event, 0, max)
	remaining := s.pending[:0]
	for _, id := range s.pending {
		me := s.events[id]
		if len(out) >= max {
			remaining = append(remaining, id)
			continue
		}
		me.claimed = true
		me.event.deliveries++
		me.event.lastAttemptAt = now
		cp := me.event
		out = append(out, &cp)
	}
	s.pending = remaining
	return out, nil
}

// AckEvent 实现 Store 接口。
func (s *MemoryStore) AckEvent(_ context.Context, eventID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.events[eventID]; !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	delete(s.events, eventID)
	return nil
}

// NackEvent 实现 Store 接口。
func (s *MemoryStore) NackEvent(_ context.Context, eventID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	me, ok := s.events[eventID]
	if !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	if !me.claimed {
		return nil // 幂等退回：未在领取中的事件无需处理
	}
	me.claimed = false
	s.pending = append(s.pending, eventID)
	return nil
}

// PendingCount 返回当前待领取事件数，便于观测与测试。
func (s *MemoryStore) PendingCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.pending)
}

// TotalEvents 返回存储中全部事件数（含领取中、待投递）。
func (s *MemoryStore) TotalEvents() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.events)
}

