			if nackErr := r.store.NackEvent(ctx, ev.ID); nackErr != nil {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		if err := r.store.AckEvent(ctx, ev.ID); err != nil {
			return res, err
		}
		res.Delivered++
	}
	return res, nil
}

// deliverOnceLeased 是启用租约后的投递路径。
//
// 取消语义：
//   - 领取后、Publish 前 ctx 已取消：事件从未交给 Publish，按当前 ClaimID
//     立即 Nack，等不到租约到期；
